def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    operations = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t = int(parts[0])
        x = int(parts[1])
        y = int(parts[2])
        operations.append((t, x, y))

    # Track earliest time to reach each banana count
    earliest = [float('inf')] * (m + 1)
    earliest[0] = 0  # Initially have 0 bananas at time 0

    for step in range(1, n + 1):
        t, x_prime, y = operations[step - 1]
        x = x_prime / 100000.0

        # Current reachable values from previous step
        prev_values = set()
        for val in range(m + 1):
            if earliest[val] < step:
                prev_values.add(val)

        next_values = set(prev_values)

        for start_k in prev_values:
            if step == 1 and start_k == 0 and t == 1 and x <= 4:
                # Special case for step 1 with type 1 and small x
                for a in range(y + 1):
                    new_k = 0
                    temp_k = start_k
                    for _ in range(a):
                        temp_k = int(temp_k + x) + (1 if (temp_k + x) != int(temp_k + x) else 0)
                        if temp_k > m:
                            break
                    new_k = temp_k
                    if new_k <= m:
                        next_values.add(new_k)
            else:
                for a in range(y + 1):
                    new_k = start_k
                    temp_k = new_k
                    for _ in range(a):
                        if t == 1:
                            # Type 1: k := ceil(k + x)
                            temp_k = int(temp_k + x)
                            if (temp_k + x) != int(temp_k + x):
                                temp_k += 1
                            temp_k = int(temp_k + x)
                            if (temp_k + x) != int(temp_k + x):
                                temp_k += 1
                            # Actually re-compute properly
                            temp_k = start_k
                            for _ in range(a):
                                temp_k = -(- (temp_k + x) // 1)  # ceil division
                            new_k = temp_k
                        else:
                            # Type 2: k := ceil(k * x)
                            temp_k = start_k
                            for _ in range(a):
                                temp_k = -(- (temp_k * x) // (x // 1)) if x > 1 else int(temp_k * x) + (1 if temp_k * x != int(temp_k * x) else 0)
                            new_k = temp_k

                        if new_k <= m and new_k >= 0:
                            next_values.add(new_k)

        earliest = [earliest[i] if earliest[i] < step else step for i in range(m + 1)]

    result = []
    for j in range(1, m + 1):
        if earliest[j] <= n:
            result.append(str(earliest[j]))
        else:
            result.append("-1")

    return ' '.join(result) + '\n'

