        # Add this component to all previously achievable sizes
        new_states = {}
        for prev_size, min_count in achievable.items():
            new_size = prev_size + size
            if new_size not in achievable or achievable[new_size] > min_count + 1:
                active = new_states.get(new_size, min_count + 1)
                new_states[new_size] = min(active, min_count + 1)

        # Also consider starting with just this component
        if size not in achievable or achievable[size] > 1:
