def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n = int(lines[0])
    abbreviations = lines[1:n+1]

    if n == 0:
        return ''

    used_suffixes = set()
    abbreviation_to_year = {}

    # Simulate the abbreviation assignment process starting from 1989
    year = 1989
    while len(abbreviation_to_year) < n:
        year_str = str(year)

        # Try suffixes from shortest (1 digit) to longest (9 digits)
        for length in range(1, 10):  # At most 9 digits as per problem
            if length <= len(year_str):
                suffix = year_str[-length:]
            else:
                suffix = year_str

            if suffix not in used_suffixes:
                # Found the shortest unused suffix for this year
                abbreviation_to_year[suffix] = year
                used_suffixes.add(suffix)
                break

        year += 1

    results = []
    for abbrev in abbreviations:
        # Extract suffix after "IAO'"
        suffix = abbrev.split("'")[1]
        results.append(str(abbreviation_to_year[suffix]))

    return '\n'.join(results)

