from collections import defaultdict

def solution(data):
    lines = data.strip().split('\n')
    if not lines:
        return "0\n"

    n, m = map(int, lines[0].split())
    edges = []
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        edges.append((u, v))

    requirements = list(map(int, lines[m + 1].split()))

    if all(r == 0 for r in requirements):
        return "0\n"

    if m == 0:
        return "-1"

    odd_cnt = sum(requirements)
    if odd_cnt % 2 != 0:
        return "-1"

    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    start = next((i + 1 for i, r in enumerate(requirements) if r == 1), None)
    if start is None:
        return "0\n"

    path = [start]
    result_path = [start]

    curr = start
    for _ in range(min(m, 4 * n - 1)):
        neighbors = adj[curr]
        if not neighbors:
            break
        curr = neighbors[0]
        path.append(curr)
        result_path.append(curr)
        if curr == start:
            break

    return f"{len(path)}\n{' '.join(map(str, path))}"


