from collections import deque, defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return '-1'

    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    # If s == t, they're already "disconnected" in a sense, but problem says s != t
    if s == t:
        return '-1'

    # Build graph and edge info
    graph = defaultdict(list)
    edges = []  # (u, v, w, idx)

    for i in range(m):
        if 2 + i < len(lines):
            parts = list(map(int, lines[2 + i].split()))
            u, v, w = parts
            graph[u].append((v, i + 1))
            graph[v].append((u, i + 1))
            edges.append((u, v, w, i + 1))

    # BFS to check if s can reach t given removed edges
    def can_reach(start, end, removed_edges):
        if removed_edges is None:
            removed_edges = set()

        visited = set()
        queue = deque([start])
        visited.add(start)

        while queue:
            u = queue.popleft()
            if u == end:
                return True  # Path exists

            for v, edge_idx in graph[u]:
                if edge_idx not in removed_edges and v not in visited:
                    visited.add(v)
                    queue.append(v)

        return False  # Path doesn't exist (nodes are disconnected)

    # Check if already disconnected (0 edges removed)
    already_disconnected = can_reach(s, t, None)
    if already_disconnected:
        return '0\n0'

    best_cost = float('inf')
    best_1_edge = None
    best_2_edges = None

    # Try removing 1 edge
    for u, v, w, idx in edges:
        if not can_reach(s, t, {idx}):
            if w < best_cost:
                best_cost = w
                best_1_edge = idx

    # Check if 1 edge solution is optimal
    if best_1_edge is not None:
        return f"{best_cost}\n1\n{best_1_edge}"

    # Try removing 2 edges
    m_edges = len(edges)
    best_2_cost = float('inf')

    for i in range(m_edges):
        u1, v1, w1, r1 = edges[i]
        for j in range(i + 1, m_edges):
            u2, v2, w2, r2 = edges[j]
            total = w1 + w2

            # Pruning: if this pair is already worse than 1-edge solution, skip
            if total >= best_1_edge:
                continue

            if not can_reach(s, t, {r1, r2}):
                if total < best_2_cost:
                    best_2_cost = total
                    best_2_edges = (r1, r2)

    if best_2_edges is not None:
        return f"{best_2_cost}\n2\n{best_2_edges[0]} {best_2_edges[1]}"

    return '-1'

