BASE = 1000000000

def get_fibonacci(n):
    """Precompute Fibonacci numbers modulo BASE"""
    f = [1, 1]
    for i in range(2, n + 2):
        f.append((f[i-1] + f[i-2]) % BASE)
    return f

class SegmentTree:
    def __init__(self, n, a):
        self.n = n
        # 2 arrays: regular sum and weighted sum
        self.tree_val = [0] * (4 * n)
        self.tree_weighted = [0] * (4 * n)
        self.lazy = [0] * (4 * n)
        self.fib = get_fibonacci(n)
        self.sum_fib_prefix = [0] * (n + 1)
        for i in range(n):
            self.sum_fib_prefix[i+1] = (self.sum_fib_prefix[i] + self.fib[i]) % BASE

        self.build(1, 0, n - 1, a)

    def build(self, node, l, r, a):
        if l == r:
            self.tree_val[node] = a[l] % BASE
            self.tree_weighted[node] = (a[l] * self.fib[l]) % BASE
        else:
            mid = (l + r) // 2
            self.build(2 * node, l, mid, a)
            self.build(2 * node + 1, mid + 1, r, a)
            self.tree_val[node] = (self.tree_val[2 * node] + self.tree_val[2 * node + 1]) % BASE
            self.tree_weighted[node] = (self.tree_weighted[2 * node] + self.tree_weighted[2 * node + 1]) % BASE

    def push(self, node, l, r):
        if self.lazy[node] != 0 and l != r:
            val = self.lazy[node]
            lazy_o = self.create_lazy()
            lazy_o[node] = self.lazy[node]
            lazy_o[2 * node] = (self.lazy[2 * node] + val) % BASE
            lazy_o[2 * node + 1] = (self.lazy[2 * node + 1] + val) % BASE

            self.tree_val[2 * node] = (self.tree_val[2 * node] + val * (mid := (l + r) // 2 - l + 1)) % BASE
            self.tree_weighted[2 * node] = (self.tree_weighted[2 * node] + val * self.sum_fib(l, mid)) % BASE

            self.tree_val[2 * node + 1] = (self.tree_val[2 * node + 1] + val * (r - mid)) % BASE
            self.tree_weighted[2 * node + 1] = (self.tree_weighted[2 * node + 1] + val * self.sum_fib(mid + 1, r)) % BASE

            self.lazy[node] = 0

    def sum_fib(self, l, r):
        if l > r:
            return 0
        return (self.sum_fib_prefix[r + 1] - self.sum_fib_prefix[l]) % BASE

    def get_mid(self, l, r):
        return (l + r) // 2

    def update(self, l, r, d):
        self._update(1, 0, self.n - 1, l, r, d)

    def _update(self, node, l, r, ql, qr, d):
        if ql > r or qr < l:
            return
        if ql <= l and r <= qr:
            self.lazy[node] = (self.lazy[node] + d) % BASE
            self.tree_val[node] = (self.tree_val[node] + d * (r - l + 1)) % BASE
            self.tree_weighted[node] = (self.tree_weighted[node] + d * self.sum_fib(l, r)) % BASE
            return
        self.push(node, l, r)
        mid = self.get_mid(l, r)
        self._update(2 * node, l, mid, ql, qr, d)
        self._update(2 * node + 1, mid + 1, r, ql, qr, d)
        self.tree_val[node] = (self.tree_val[2 * node] + self.tree_val[2 * node + 1]) % BASE
        self.tree_weighted[node] = (self.tree_weighted[2 * node] + self.tree_weighted[2 * node + 1]) % BASE

    def point_update(self, idx, val):
        self._point_update(1, 0, self.n - 1, idx, val)

    def _point_update(self, node, l, r, idx, val):
        if l == r:
            self.tree_val[node] = val % BASE
            self.tree_weighted[node] = (val * self.fib[l]) % BASE
            return
        self.push(node, l, r)
        mid = self.get_mid(l, r)
        if idx <= mid:
            self._point_update(2 * node, l, mid, idx, val)
        else:
            self._point_update(2 * node + 1, mid + 1, r, idx, val)
        self.tree_val[node] = (self.tree_val[2 * node] + self.tree_val[2 * node + 1]) % BASE
        self.tree_weighted[node] = (self.tree_weighted[2 * node] + self.tree_weighted[2 * node + 1]) % BASE

    def query(self, l, r):
        return self._query(1, 0, self.n - 1, l, r)

    def _query(self, node, l, r, ql, qr):
        if ql > r or qr < l:
            return 0
        if ql <= l and r <= qr:
            return (self.tree_weighted[node], self.tree_val[node])
        self.push(node, l, r)
        mid = self.get_mid(l, r)
        res = ((self._query(2 * node, l, mid, ql, qr),
                 self._query(2 * node + 1, mid + 1, r, ql, qr))
            )
        # Merge results
        return (res[0][0] + res[1][0]) % BASE, (res[0][1] + res[1][1]) % BASE

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) == 0:
        return ''

    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Convert to 0-indexed and working with segments
    tree = SegmentTree(n, a)

    output = []
    for line in lines[2:]:
        if not line.strip():
            continue
        parts = line.strip().split()
        t = int(parts[0])
        if t == 1:
            x = int(parts[1]) - 1
            v = int(parts[2])
            tree.point_update(x, v % BASE)
        elif t == 2:
            l = int(parts[1]) - 1
            r = int(parts[2]) - 1
            result = tree.query(l, r)[0] % BASE
            if result < 0:
                result += BASE
            output.append(str(result))
        else:
            l = int(parts[1]) - 1
            r = int(parts[2]) - 1
            d = int(parts[3])
            tree.update(l, r, d % BASE)

    return '\n'.join(output)

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    try:
        n, m = map(int, lines[0].split())
    except:
        return input_str

    grid = []
    for i in range(1, n + 1):
        if i < len(lines):
            grid.append(list(lines[i]))

    if len(grid) == 0 or n == 0 or m == 0:
        return input_str

    # Find all connected components of free cells (4-directional connectivity)
    visited = [[False] * m for _ in range(n)]
    components = []

    for i in range(n):
        for j in range(min(m, len(grid[i]))):  # Safety check
            if grid[i][j] == '.' and not visited[i][j]:
                component = []
                stack = [(i, j)]
                visited[i][j] = True

                while stack:
                    r, c = stack.pop()
                    component.append((r, c))

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < min(m, len(grid[nr])):
                            if grid[nr][nc] == '.' and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))

                components.append(set(component))

    # For each connected component, make sure all cells in its bounding box are free
    for comp in components:
        rows = [r for r, c in comp]
        cols = [c for r, c in comp]

        min_r, max_r = min(rows), max(rows)
        min_c, max_c = min(cols), max(cols)

        # Fill the bounding box with free cells
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                if 0 <= r < n and 0 <= c < len(grid[r]):
                    grid[r][c] = '.'

    # Reconstruct output
    result_lines = []
    for i in range(n):
        row_str = ''.join(grid[i])
        while len(row_str) < m:  # Pad if needed (safety)
            row_str += '.'
        result_lines.append(row_str[:m])

    return '\n'.join(result_lines) + '\n'

