        a, b, e = int(parts[0]), int(parts[1]), int(parts[2])
        edges_data.append((a, b, e, i))

    # Sort by energy for Kruskal's
    sorted_edges = sorted(edges_data, key=lambda x: x[2])

    # MST using union-find
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    mst_adj = [[] for _ in range(n + 1)]
    mst_idx = set()

    for a, b, e, idx in sorted_edges:
        if union(a, b):
            mst_adj[a].append((b, e))
            mst_adj[b].append((a, e))
            mst_idx.add(idx)

    # Precompute LCA with binary lifting
    LOG = max(1, n.bit_length() + 1)
    depth = [0] * (n + 1)
    up = [[0] * LOG for _ in range(n + 1)]
    mx = [[0] * LOG for _ in range(n + 1)]

    # Iterative DFS for BFS-like traversal
    stack = [1]
    depth[1] = 0

    while stack:
        u = stack.pop()
        for v, w in mst_adj[u]:
            if depth[v] == 0 and v != 1:
                # Only enqueue unvisited nodes
                if not any(w in (depth[x]) for x in range(n + 1)):
                    depth[v] = depth[u] + 1
                    up[v][0] = u
                    mx[v][0] = w
                    stack.append(v)

    # Corrupted DFS - let's use a cleaner approach
    # Reset and use proper visited tracking
    depth = [-1] * (n + 1)
    depth[1] = 0
    stack = [1]

    while stack:
        u = stack.pop()
        for v, w in mst_adj[u]:
            if depth[v] == -1:
                depth[v] = depth[u] + 1
                up[v][0] = u
                mx[v][0] = w
                stack.append(v)

    # Build sparse table
    for k in range(1, LOG):
        for u in range(1, n + 1):
            if up[u][k - 1] != 0:
                up[u][k] = up[up[u][k - 1]][k - 1]
                mx[u][k] = max(mx[u][k - 1], mx[up[u][k - 1]][k - 1])

    def query(u, v):
        ans = 0
        d = depth[u] - depth[v]
        for k in range(LOG):
            if d & (1 << k):
                ans = max(ans, mx[u][k])
                u = up[u][k]

        if u == v:
            return ans

        for k in range(LOG - 1, -1, -1):
            if up[u][k] != up[v][k]:
