                ans = max(ans, mx[v][k])
                u = up[u][k]
                v = up[v][k]

        return max(ans, mx[u][0], mx[v][0])

    results = []
    for a, b, e, i in edges_data:
        if i not in mst_idx:
            results.append(str(query(a, b)))

    return '\n'.join(results)

