class SegmentTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.tree_sum = [0] * (4 * self.n)
        self.tree_max = [0] * (4 * self.n)
        self.lazy = [0] * (4 * self.n)
        self.build(arr, 1, 0, self.n - 1)

    def build(self, arr, node, start, end):
        if start == end:
            self.tree_sum[node] = arr[start]
            self.tree_max[node] = arr[start]
        else:
            mid = (start + end) // 2
            self.build(arr, 2 * node, start, mid)
            self.build(arr, 2 * node + 1, mid + 1, end)
            self.tree_sum[node] = self.tree_sum[2 * node] + self.tree_sum[2 * node + 1]
            self.tree_max[node] = max(self.tree_max[2 * node], self.tree_max[2 * node + 1])

    def push(self, node, start, end):
        if self.lazy[node] != 0:
            mid = (start + end) // 2
            self.lazy[2 * node] += self.lazy[node]
            self.tree_sum[2 * node] += self.lazy[node] * (mid - start + 1)
            self.tree_max[2 * node] += self.lazy[node]

            self.lazy[2 * node + 1] += self.lazy[node]
            self.tree_sum[2 * node + 1] += self.lazy[node] * (end - mid)
            self.tree_max[2 * node + 1] += self.lazy[node]

            self.lazy[node] = 0

    def range_add(self, l, r, x, node, start, end):
        if start > end or start > r or end < l:
            return
        if start >= l and end <= r:
            self.lazy[node] += x
            self.tree_sum[node] += x * (end - start + 1)
            self.tree_max[node] += x
        else:
            self.push(node, start, end)
            mid = (start + end) // 2
            self.range_add(l, r, x, 2 * node, start, mid)
            self.range_add(l, r, x, 2 * node + 1, mid + 1, end)
            self.tree_sum[node] = self.tree_sum[2 * node] + self.tree_sum[2 * node + 1]
            self.tree_max[node] = max(self.tree_max[2 * node], self.tree_max[2 * node + 1])

    def query_sum(self, l, r, node, start, end):
        if start > end or start > r or end < l:
            return 0
        if start >= l and end <= r:
            return self.tree_max[node]

