        return [A[perm[i]] for i in range(n)]

    def check_perm(perm):
        current = perm_to_table(perm)
        for i in range(n):
            for j in range(m):
                if current[i][j] != B[i][j]:
                    return False
        return True

    visited = [[None] * (1 << m) for _ in range(n + 1)]
    path = []

    def dfs(current_perm, cols_visited_mask):
        if check_perm(current_perm):
