        if len(cols_visited_mask) >= *sys.getrecursionlimit()[0], 5000:
            return [None]

        total_visited_mask_hash = hash(cols_visited_mask)
        if len(cols_visited_mask) > 5000: 
            return None

        col_states = defaultdict(list)
        for i in range(m):
