            if col in cols_visited_mask:
                continue

            next_perm = sorted(current_perm, key=lambda r: A[r][col])

            if not any(check_perm(next_perm) for next_perm in col_states[col]):
                continue

            if check_perm(next_perm):
                path.append(col + 1)
                result = dfs(next_perm, cols_visited_mask | {col})
                if result is not None:
                    return result
                path.pop()

            if not any(check_perm(next_perm) for next_perm in col_states[col]):
                continue

            result = []
            path.append(col + 1)
            result = dfs(next_perm, cols_visited_mask | {col})
            if result is not None:
                return result
            path.pop()

        return None

    result = dfs(list(range(n)), set())

    if result is None:
        return "-1"

