import math

def solution(input_str):
    l, r = map(int, input_str.strip().split())

    if l > r:
        return "0\n"

    if l == 1:
        l = 2

    # Upper bound for sqrt(r) to find initial primes
    sqrt_r = int(math.isqrt(r))

    if sqrt_r < 2:
        count = 0
    else:
        # Sieve of Eratosthenes up to sqrt(r)
        is_prime_base = [True] * (sqrt_r + 1)
        is_prime_base[0] = is_prime_base[1] = False

        p = 2
        while p * p <= sqrt_r:
            if is_prime_base[p]:
                for i in range(p * p, sqrt_r + 1, p):
                    is_prime_base[i] = False
            p += 1

        primes = [p for p in range(2, sqrt_r + 1) if is_prime_base[p]]

        # Segmented sieve for [l, r]
        n = r - l + 1
        is_prime_l = [True] * n

        for p in primes:
            # Find first multiple of p >= l
            start = max(p * p, ((l + p - 1) // p) * p)
            for i in range(start, r + 1, p):
                is_prime_l[i - l] = False

        # Count primes in [l, r] that are 2 or ≡ 1 (mod 4)
        count = 0
        for i in range(n):
            if is_prime_l[i]:
                num = l + i
                if num == 2 or num % 4 == 1:
                    count += 1

    return f"{count}\n"

