                    # Standard Li Chao - compare at mid
                    old_m, old_c = tree[node]
                    val_old = old_m * sorted_q[mid] + c
                    if val1 > val_old:
                        tree[node] = (m, c)
                        # Still may add to children
                        if l != r:
                            add_line(l, mid - 1, old_m, old_c, 2 * node, nl, nr)
                            add_line(mid + 1, r, m, c, 2 * node + 1, nl, nr)
